curl -s http://localhost:8080/api/processes | python3 -c "
import json,sys
d=json.load(sys.stdin)
procs=d.get('data',d)
if isinstance(procs,list):
    counts={}
    for p in procs:
        c=p.get('container',{}).get('state','?')
        counts[c]=counts.get(c,0)+1
    print('state counts:',counts)
    for p in procs:
        if p.get('container',{}).get('state')!='running':
            print('NOT RUNNING:',p.get('name'),p.get('container',{}).get('state'),p.get('container',{}).get('last_exit_code'))
else:
    print(json.dumps(d)[:500])
"
